#!/usr/bin/env python3
"""shipctl: a CLI release task manager (stdlib only)."""
import argparse
import datetime
import json
import os
import re
import sys
import tempfile


class UserError(Exception):
    """Bad input or unknown id (exit 1)."""


class StorageError(Exception):
    """Storage or I/O failure (exit 2)."""


DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def db_path():
    return os.environ.get("SHIPCTL_DB") or "./tasks.json"


def _empty():
    return {"version": 1, "next_id": 1, "tasks": []}


def _valid(data):
    if not isinstance(data, dict):
        return False
    if not isinstance(data.get("next_id"), int) or isinstance(data["next_id"], bool):
        return False
    tasks = data.get("tasks")
    if not isinstance(tasks, list):
        return False
    for t in tasks:
        if not isinstance(t, dict):
            return False
        if not isinstance(t.get("id"), int) or isinstance(t["id"], bool):
            return False
        if not isinstance(t.get("title"), str):
            return False
        if t.get("status") not in ("pending", "done"):
            return False
        if t.get("owner") is not None and not isinstance(t["owner"], str):
            return False
        due = t.get("due")
        if due is not None and not (isinstance(due, str) and DATE_RE.match(due)):
            return False
    return True


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            text = f.read()
    except FileNotFoundError:
        return _empty()
    except (OSError, UnicodeDecodeError) as e:
        raise StorageError(f"cannot read {path}: {e}")
    try:
        data = json.loads(text)
    except ValueError as e:
        raise StorageError(f"{path} is corrupt (invalid JSON: {e})")
    if not _valid(data):
        raise StorageError(f"{path} is corrupt (unexpected structure)")
    return data


def save(path, data):
    directory = os.path.dirname(os.path.abspath(path))
    tmp = None
    try:
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".shipctl-", suffix=".tmp")
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)
            f.write("\n")
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
        tmp = None
    except OSError as e:
        raise StorageError(f"cannot write {path}: {e}")
    finally:
        if tmp is not None:
            try:
                os.unlink(tmp)
            except OSError:
                pass


def parse_date(s):
    if not DATE_RE.match(s):
        raise UserError(f"invalid date '{s}' (expected YYYY-MM-DD)")
    try:
        datetime.date.fromisoformat(s)
    except ValueError:
        raise UserError(f"invalid date '{s}' (expected YYYY-MM-DD)")
    return s


def find_task(data, task_id):
    for t in data["tasks"]:
        if t["id"] == task_id:
            return t
    raise UserError(f"#{task_id} not found")


def sort_key(task):
    return (task["due"] is None, task["due"] or "", task["id"])


def cmd_add(args, data):
    title = args.title.strip()
    if not title:
        raise UserError("title must not be empty")
    task_id = data["next_id"]
    data["next_id"] = task_id + 1
    data["tasks"].append(
        {"id": task_id, "title": title, "owner": None, "due": None, "status": "pending"}
    )
    return True, f"Added #{task_id}: {title}"


def cmd_assign(args, data):
    owner = args.owner.strip()
    if not owner:
        raise UserError("owner must not be empty")
    task = find_task(data, args.id)
    task["owner"] = owner
    return True, f"Assigned #{task['id']} to {owner}"


def cmd_due(args, data):
    date = parse_date(args.date)
    task = find_task(data, args.id)
    task["due"] = date
    return True, f"Due #{task['id']}: {date}"


def cmd_done(args, data):
    task = find_task(data, args.id)
    task["status"] = "done"
    return True, f"Completed #{task['id']}"


def cmd_delete(args, data):
    task = find_task(data, args.id)
    data["tasks"].remove(task)
    return True, f"Deleted #{task['id']}"


def cmd_list(args, data):
    tasks = data["tasks"]
    if args.status != "all":
        tasks = [t for t in tasks if t["status"] == args.status]
    if args.owner is not None:
        want = args.owner.casefold()
        tasks = [t for t in tasks if t["owner"] and t["owner"].casefold() == want]
    if not tasks:
        return False, "No tasks."
    lines = [
        f"#{t['id']}  {t['due'] or '-'}  {t['owner'] or '-'}  [{t['status']}]  {t['title']}"
        for t in sorted(tasks, key=sort_key)
    ]
    return False, "\n".join(lines)


class _Parser(argparse.ArgumentParser):
    def error(self, message):
        raise UserError(message)


def build_parser():
    p = _Parser(prog="shipctl", description="Release task manager.")
    sub = p.add_subparsers(dest="command", required=True, parser_class=_Parser)

    s = sub.add_parser("add", help="add a task")
    s.add_argument("title")
    s.set_defaults(func=cmd_add)

    s = sub.add_parser("assign", help="assign an owner")
    s.add_argument("id", type=int)
    s.add_argument("owner")
    s.set_defaults(func=cmd_assign)

    s = sub.add_parser("due", help="set a due date (YYYY-MM-DD)")
    s.add_argument("id", type=int)
    s.add_argument("date")
    s.set_defaults(func=cmd_due)

    s = sub.add_parser("list", help="list tasks")
    s.add_argument("--owner")
    s.add_argument("--status", choices=["pending", "done", "all"], default="pending")
    s.set_defaults(func=cmd_list)

    s = sub.add_parser("done", help="mark a task completed")
    s.add_argument("id", type=int)
    s.set_defaults(func=cmd_done)

    s = sub.add_parser("delete", help="delete a task")
    s.add_argument("id", type=int)
    s.set_defaults(func=cmd_delete)
    return p


def main(argv=None):
    try:
        args = build_parser().parse_args(argv)
        path = db_path()
        data = load(path)
        changed, message = args.func(args, data)
        if changed:
            save(path, data)
        print(message)
        return 0
    except UserError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    except StorageError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())

